Properties p = new Properties();
p.put("acks", "all");              // durability: leader + ISR must ack
p.put("enable.idempotence", "true"); // dedupe producer retries, per-partition order
p.put("compression.type", "lz4");    // trade CPU for network/disk
p.put("batch.size", 65536);           // bigger batch = more throughput
p.put("linger.ms", 20);               // wait to fill batch = more latency
p.put("max.in.flight.requests.per.connection", 5); // keep pipelined with idempotence
p.put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
// key = routing + order + idempotency. Null key = no order, even spread.
